inline float levelTrim (int mode, float drive)
{
    const auto& table = levelTrimDb[(size_t) juce::jlimit (0, 2, mode)];
    const float pos = juce::jlimit (0.0f, 1.0f, drive) * (float) (levelTrimSteps - 1);
    const int i = juce::jmin ((int) pos, levelTrimSteps - 2);
    const float t = pos - (float) i;
    return table[(size_t) i] + t * (table[(size_t) i + 1] - table[(size_t) i]);
}

